package xyz.shuncongci.leica

import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import java.io.ByteArrayOutputStream
import java.io.DataOutputStream
import java.io.File
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.concurrent.CancellationException

class CaptureMetadataContainerTest {
    @get:Rule val temp=TemporaryFolder()
    private var index=0
    private val metadata get()=CaptureExif(CaptureMetadataFixtures.tiff()).normalized(16,12)
    private fun rewrite(bytes:ByteArray,exif:ByteArray=metadata):Pair<File,File>{
        val dir=temp.newFolder("case-${index++}");val source=File(dir,"source").apply{writeBytes(bytes)};val target=File(dir,"target")
        CaptureMetadataContainer.write(source,target,exif,16,12,Cancel());return source to target
    }
    private data class Span(val at:Int,val marker:Int,val n:Int,val payload:ByteArray)
    private fun headers(b:ByteArray):List<Span>{var at=2;val spans=mutableListOf<Span>();while(b[at+1].toInt() and 255!=0xda){val n=((b[at+2].toInt() and 255) shl 8)+(b[at+3].toInt() and 255);spans+=Span(at,b[at+1].toInt() and 255,n+2,b.copyOfRange(at+4,at+n+2));at+=n+2};return spans}
    private fun isExif(s:Span)=s.marker==0xe1 && s.payload.size>=6 && String(s.payload,0,6)=="Exif\u0000\u0000"
    private fun stripExif(bytes:ByteArray):ByteArray{val out=ByteArrayOutputStream();out.write(bytes,0,2);val h=headers(bytes);h.filterNot(::isExif).forEach{out.write(bytes,it.at,it.n)};val tail=h.last().let{it.at+it.n};out.write(bytes,tail,bytes.size-tail);return out.toByteArray()}
    private fun tail(bytes:ByteArray)=headers(bytes).last().let{bytes.copyOfRange(it.at+it.n,bytes.size)}
    private fun segment(marker:Int,payload:ByteArray):ByteArray{val out=ByteArrayOutputStream();DataOutputStream(out).use{it.writeByte(255);it.writeByte(marker);it.writeShort(payload.size+2);it.write(payload)};return out.toByteArray()}
    private fun hdr(base:ByteArray=CaptureMetadataFixtures.jpeg):ByteArray=ByteArrayOutputStream().also{UltraHdrContainer.write(it,base,CaptureMetadataFixtures.jpeg,HdrMath.Map(16,12,IntArray(192),1f,4f,4f))}.toByteArray()
    private fun primarySize(bytes:ByteArray):Int{val s=headers(bytes).single{it.marker==0xe2 && it.payload.take(4).toByteArray().contentEquals(byteArrayOf(77,80,70,0))};val p=CaptureExif(s.payload.copyOfRange(4,s.payload.size));val entry=p.root().first{it.tag==0xb002};val offset=ByteBuffer.wrap(entry.raw).order(p.order).getInt(8);val size=ByteBuffer.wrap(s.payload).order(p.order).getInt(4+offset+4);val gainOffset=ByteBuffer.wrap(s.payload).order(p.order).getInt(4+offset+24);assertEquals(size,s.at+8+gainOffset);assertEquals(255,bytes[size].toInt() and 255);assertEquals(216,bytes[size+1].toInt() and 255);return size}
    private data class Chunk(val kind:String,val data:ByteArray,val encoded:ByteArray)
    private fun pngChunks(bytes:ByteArray):List<Chunk>{var at=8;val out=mutableListOf<Chunk>();while(at<bytes.size){val n=ByteBuffer.wrap(bytes).getInt(at);val end=at+n+12;out+=Chunk(String(bytes,at+4,4),bytes.copyOfRange(at+8,at+8+n),bytes.copyOfRange(at,end));at=end};return out}
    private fun webpChunks(bytes:ByteArray):List<Chunk>{var at=12;val out=mutableListOf<Chunk>();while(at<bytes.size){val n=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN).getInt(at+4);val end=at+n+8+n%2;out+=Chunk(String(bytes,at,4),bytes.copyOfRange(at+8,at+8+n),bytes.copyOfRange(at,end));at=end};return out}
    @Test fun jpegMetadataRoundTrips(){val (_,out)=rewrite(CaptureMetadataFixtures.jpeg);assertArrayEquals(metadata,CaptureMetadataContainer.readExif(out).exif)}
    @Test fun jpegCaptureAndLensAreReadable(){val (_,out)=rewrite(CaptureMetadataFixtures.jpeg);val p=CaptureExif(checkNotNull(CaptureMetadataContainer.readExif(out).exif));assertEquals("Fixture\u0000",String(checkNotNull(p.value(false,0x10f))));assertEquals("FixtureLens\u0000",String(checkNotNull(p.value(true,0xa434))))}
    @Test fun jpegEntropyAndAllOtherHeadersAreByteExact(){val (_,out)=rewrite(CaptureMetadataFixtures.jpeg);assertArrayEquals(CaptureMetadataFixtures.jpeg,stripExif(out.readBytes()));assertArrayEquals(tail(CaptureMetadataFixtures.jpeg),tail(out.readBytes()))}
    @Test fun replacingJpegExifDoesNotCreateDuplicatePackets(){val (_,first)=rewrite(CaptureMetadataFixtures.jpeg);val next=CaptureExif(metadata).normalized(16,12,XiaomiLeicaBadge.patches(CaptureExif(metadata),true));val (_,out)=rewrite(first.readBytes(),next);assertEquals(1,headers(out.readBytes()).count(::isExif));assertArrayEquals(next,CaptureMetadataContainer.readExif(out).exif);assertArrayEquals(CaptureMetadataFixtures.jpeg,stripExif(out.readBytes()))}
    @Test fun jpegOverCapacityFailsWithoutTouchingSource(){val dir=temp.newFolder();val source=File(dir,"source").apply{writeBytes(CaptureMetadataFixtures.jpeg)};val target=File(dir,"target");val large=CaptureExif.empty().normalized(16,12,listOf(CaptureExif.Patch(true,0x9286,7,ByteArray(66000))));assertThrows(IllegalArgumentException::class.java){CaptureMetadataContainer.write(source,target,large,16,12,Cancel())};assertFalse(target.exists());assertArrayEquals(CaptureMetadataFixtures.jpeg,source.readBytes())}
    @Test fun ultraHdrKeepsCompleteGainJpegAndXmp(){val before=hdr();val start=primarySize(before);val (_,out)=rewrite(before);val after=out.readBytes();val updated=primarySize(after);assertArrayEquals(before.copyOfRange(start,before.size),after.copyOfRange(updated,after.size));assertArrayEquals(tail(before),tail(after));assertArrayEquals(metadata,CaptureMetadataContainer.readExif(out).exif);assertTrue(String(after,Charsets.ISO_8859_1).contains("hdrgm:GainMapMax=\"2.0\""))}
    @Test fun ultraHdrReplacementBeforeMpfUpdatesPrimarySize(){val (_,first)=rewrite(hdr());val before=first.readBytes();val p=CaptureExif(metadata);val more=p.normalized(16,12,XiaomiLeicaBadge.patches(p,true));val (_,out)=rewrite(before,more);val after=out.readBytes();assertArrayEquals(before.copyOfRange(primarySize(before),before.size),after.copyOfRange(primarySize(after),after.size))}
    @Test fun ultraHdrOldExifAfterMpfAdjustsRelativeGainOffset(){val base=CaptureMetadataFixtures.jpeg;val withExif=base.copyOfRange(0,2)+segment(0xe1,"Exif\u0000\u0000".toByteArray()+metadata)+base.copyOfRange(2,base.size);val before=hdr(withExif);val (_,out)=rewrite(before);val after=out.readBytes();assertArrayEquals(before.copyOfRange(primarySize(before),before.size),after.copyOfRange(primarySize(after),after.size));assertArrayEquals(tail(before),tail(after))}
    @Test fun invalidHdrIndexFailsClosed(){val before=hdr();val s=headers(before).first{it.marker==0xe2 && String(it.payload,0,4)=="MPF\u0000"};ByteBuffer.wrap(before).putInt(s.at+82,1);assertThrows(IllegalArgumentException::class.java){rewrite(before)}}
    @Test fun pngMetadataRoundTripsWithValidCrc(){val (_,out)=rewrite(CaptureMetadataFixtures.png);assertArrayEquals(metadata,CaptureMetadataContainer.readExif(out).exif);assertEquals(1,pngChunks(out.readBytes()).count{it.kind=="eXIf"})}
    @Test fun pngPixelsAndExistingChunksAreByteExact(){val (_,out)=rewrite(CaptureMetadataFixtures.png);val original=pngChunks(CaptureMetadataFixtures.png);val after=pngChunks(out.readBytes()).filterNot{it.kind=="eXIf"};assertEquals(original.size,after.size);original.zip(after).forEach{(a,b)->assertArrayEquals(a.encoded,b.encoded)}}
    @Test fun replacingPngExifDoesNotDuplicate(){val (_,first)=rewrite(CaptureMetadataFixtures.png);val (_,out)=rewrite(first.readBytes());assertEquals(1,pngChunks(out.readBytes()).count{it.kind=="eXIf"})}
    @Test fun pngCorruptMetadataCrcIsRejected(){val (_,out)=rewrite(CaptureMetadataFixtures.png);val bytes=out.readBytes();val packet=pngChunks(bytes).first{it.kind=="eXIf"};val start=bytes.indexOfSubsequence(packet.encoded);bytes[start+packet.encoded.size-1]=(bytes[start+packet.encoded.size-1].toInt() xor 1).toByte();out.writeBytes(bytes);assertThrows(IllegalArgumentException::class.java){CaptureMetadataContainer.readExif(out)}}
    @Test fun pngWrongDimensionsDoNotPublish(){val source=temp.newFile().apply{writeBytes(CaptureMetadataFixtures.png)};val target=File(temp.root,"wrong-size");assertThrows(IllegalArgumentException::class.java){CaptureMetadataContainer.write(source,target,metadata,12,16,Cancel())};assertFalse(target.exists())}
    @Test fun webpMetadataAndRiffLengthAreValid(){val (_,out)=rewrite(CaptureMetadataFixtures.webp);val bytes=out.readBytes();assertEquals(bytes.size-8,ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN).getInt(4));assertEquals(8,webpChunks(bytes).first().data[0].toInt() and 8);assertArrayEquals(metadata,CaptureMetadataContainer.readExif(out).exif)}
    @Test fun webpLossyImageBytesAreUntouched(){val (_,out)=rewrite(CaptureMetadataFixtures.webp);assertArrayEquals(webpChunks(CaptureMetadataFixtures.webp).single{it.kind=="VP8 "}.data,webpChunks(out.readBytes()).single{it.kind=="VP8 "}.data)}
    @Test fun webpLosslessImageBytesAreUntouched(){val (_,out)=rewrite(CaptureMetadataFixtures.losslessWebp);assertArrayEquals(webpChunks(CaptureMetadataFixtures.losslessWebp).single{it.kind=="VP8L"}.data,webpChunks(out.readBytes()).single{it.kind=="VP8L"}.data);assertArrayEquals(metadata,CaptureMetadataContainer.readExif(out).exif)}
    @Test fun webpExtendedReplacementDoesNotDuplicate(){val (_,first)=rewrite(CaptureMetadataFixtures.webp);val (_,out)=rewrite(first.readBytes());assertEquals(1,webpChunks(out.readBytes()).count{it.kind=="EXIF"});assertEquals(1,webpChunks(out.readBytes()).count{it.kind=="VP8X"})}
    @Test fun webpOddExifUsesPaddingOutsidePayload(){val odd=metadata+byteArrayOf(0);assertEquals(1,odd.size%2);val (_,out)=rewrite(CaptureMetadataFixtures.webp,odd);assertArrayEquals(odd,CaptureMetadataContainer.readExif(out).exif);assertEquals(out.length()-8,ByteBuffer.wrap(out.readBytes()).order(ByteOrder.LITTLE_ENDIAN).getInt(4).toLong())}
    @Test fun sourceIsNotModified(){for(bytes in listOf(CaptureMetadataFixtures.jpeg,CaptureMetadataFixtures.png,CaptureMetadataFixtures.webp,CaptureMetadataFixtures.losslessWebp)){val (source,_)=rewrite(bytes);assertArrayEquals(bytes,source.readBytes())}}
    @Test fun existingTargetIsNeverOverwritten(){val source=temp.newFile().apply{writeBytes(CaptureMetadataFixtures.jpeg)};val target=temp.newFile().apply{writeText("untouched")};assertThrows(IllegalStateException::class.java){CaptureMetadataContainer.write(source,target,metadata,16,12,Cancel())};assertEquals("untouched",target.readText())}
    @Test fun samePathIsRejectedWithoutTouchingImage(){val source=temp.newFile().apply{writeBytes(CaptureMetadataFixtures.jpeg)};assertThrows(IllegalArgumentException::class.java){CaptureMetadataContainer.write(source,source,metadata,16,12,Cancel())};assertArrayEquals(CaptureMetadataFixtures.jpeg,source.readBytes())}
    @Test fun cancelledMetadataWriteLeavesNoPartial(){val source=temp.newFile().apply{writeBytes(CaptureMetadataFixtures.jpeg)};val target=File(temp.root,"cancelled");val cancel=Cancel().apply{cancelled=true};assertThrows(CancellationException::class.java){CaptureMetadataContainer.write(source,target,metadata,16,12,cancel)};assertFalse(target.exists());assertArrayEquals(CaptureMetadataFixtures.jpeg,source.readBytes())}
    @Test fun unsupportedSourceRequiresPlatformFallback(){val source=temp.newFile().apply{writeBytes("\u0000\u0000\u0000\u0018ftypheic".toByteArray())};assertFalse(CaptureMetadataContainer.readExif(source).supported)}
    @Test fun standardJpegWithoutExifIsSupportedNotInvented(){val source=temp.newFile().apply{writeBytes(CaptureMetadataFixtures.jpeg)};val read=CaptureMetadataContainer.readExif(source);assertTrue(read.supported);assertNull(read.exif);assertFalse(read.otherMetadata)}
    @Test fun additionalDescriptiveXmpPreventsCompleteMetadataClaim(){val bytes=CaptureMetadataFixtures.jpeg;val xmp=segment(0xe1,"http://ns.adobe.com/xap/1.0/\u0000<dc:title>synthetic</dc:title>".toByteArray());val source=temp.newFile().apply{writeBytes(bytes.copyOfRange(0,2)+xmp+bytes.copyOfRange(2,bytes.size))};assertTrue(CaptureMetadataContainer.readExif(source).otherMetadata)}
    @Test fun truncatedChunkIsRejectedBeforeAllocation(){val bytes=CaptureMetadataFixtures.png;ByteBuffer.wrap(bytes).putInt(8,Int.MAX_VALUE);val source=temp.newFile().apply{writeBytes(bytes)};assertThrows(IllegalArgumentException::class.java){CaptureMetadataContainer.readExif(source)}}
    private fun ByteArray.indexOfSubsequence(needle:ByteArray):Int=(0..size-needle.size).first{start->needle.indices.all{this[start+it]==needle[it]}}
}
